BEGIN TRANSACTION READ ONLY;SET LOCAL statement_timeout='20s';SET LOCAL search_path=pg_catalog;
SELECT jsonb_build_object('captured_at',clock_timestamp(),'tables',(SELECT jsonb_agg(jsonb_build_object('name',n.nspname||'.'||c.relname,'triggers',COALESCE((SELECT jsonb_agg(jsonb_build_object('definition',pg_get_triggerdef(t.oid),'signature',t.tgfoid::regprocedure::text,'function',pg_get_functiondef(t.tgfoid),'md5',md5(pg_get_functiondef(t.tgfoid)),'enabled',t.tgenabled) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal),'[]'::jsonb),'rules',COALESCE((SELECT jsonb_agg(pg_get_ruledef(r.oid) ORDER BY r.rulename) FROM pg_rewrite r WHERE r.ev_class=c.oid),'[]'::jsonb)) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname||'.'||c.relname IN('auth.users','public.app_accounts','public.app_profiles','public.ai_conversations','private.account_lineage_v5','private.worker_ai_sessions','private.worker_ai_reviews','private.worker_ai_saves','private.work_taxonomy_gemini_turn_hints_v1','private.work_taxonomy_review_outbox_v1','private.work_taxonomy_review_batches_v1','private.work_taxonomy_worker_bindings_v1','private.worker_execution_mode_choices','private.work_taxonomy_worker_capabilities','private.taxonomy_confirmed_worker_modes_v1','private.work_taxonomy_related_acceptances','private.dispatch_schedule')),
'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'md5',md5(pg_get_functiondef(p.oid))) ORDER BY p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('private','public') AND p.proname IN('enqueue_dispatch','account_lineage','account_visibility_world','requeue_open_needs_for_worker_v5','sync_worker_skills_to_taxonomy_capabilities','metadata_text_array','validate_need_v2_fact','closure_assert_open','closure_account_restricted','closure_taxonomy_profile_erasing_v1','rpc_read_worker_ai_taxonomy','worker_ai_document','worker_ai_service_mode_context_v1','taxonomy_review_exact_projection_v1','taxonomy_review_candidate_projection_v2'))) AS capture;ROLLBACK;
